+@page "/catalog"
+@using sv_f76eba3b769e4364bcb12e86bebe0f6d.Services
+@inject IProductService ProductService
+@rendermode InteractiveServer
+
+<PageTitle>Product Catalog</PageTitle>
+
+<div class="d-flex">
+    @* ── Left Sidebar (Filters) ── *@
+    <aside class="p-3 border-end bg-light" style="width:25%; min-width:220px;">
+        <h5>Filters</h5>
+
+        @* Category checkboxes *@
+        <div class="mb-3">
+            <label class="form-label fw-semibold">Category</label>
+            @if (categories is not null)
+            {
+                @foreach (var cat in categories)
+                {
+                    <div class="form-check">
+                        <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
+                               checked="@selectedCategories.Contains(cat)"
+                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
+                        <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
+                    </div>
+                }
+            }
+        </div>
+
+        @* Price range *@
+        <div class="mb-3">
+            <label class="form-label fw-semibold">Price Range</label>
+            <div class="d-flex gap-2">
+                <input type="number" class="form-control form-control-sm" placeholder="Min"
+                       @bind="minPrice" @bind:event="oninput" min="0" />
+                <input type="number" class="form-control form-control-sm" placeholder="Max"
+                       @bind="maxPrice" @bind:event="oninput" min="0" />
+            </div>
+        </div>
+
+        @* In Stock toggle *@
+        <div class="form-check mb-3">
+            <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
+            <label class="form-check-label" for="inStockOnly">In Stock Only</label>
+        </div>
+
+        <div class="d-grid gap-2">
+            <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
+            <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
+        </div>
+    </aside>
+
+    @* ── Main Content ── *@
+    <main class="p-3 flex-grow-1" style="width:75%;">
+
+        @if (errorMessage is not null)
+        {
+            <div class="alert alert-danger" role="alert">@errorMessage</div>
+        }
+        else if (isLoading)
+        {
+            <div class="d-flex justify-content-center align-items-center" style="min-height:300px;">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading…</span>
+                </div>
+            </div>
+        }
+        else if (result is null || result.Items.Count == 0)
+        {
+            <div class="text-center text-muted py-5">
+                <h4>No products found</h4>
+                <p>Try adjusting your filters.</p>
+            </div>
+        }
+        else
+        {
+            @* Toolbar *@
+            <div class="d-flex justify-content-between align-items-center mb-3">
+                <div>
+                    <label class="form-label me-2 mb-0">Sort by:</label>
+                    <select class="form-select form-select-sm d-inline-block w-auto"
+                            @bind="sortBy" @bind:after="OnSortChanged">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A–Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="text-muted">
+                    Showing @ShowingStart–@ShowingEnd of @result.TotalCount products
+                </span>
+            </div>
+
+            @* Product grid *@
+            <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
+                @foreach (var product in result.Items)
+                {
+                    <div class="col">
+                        <ProductCard Product="product" OnProductSelected="OnProductSelected" />
+                    </div>
+                }
+            </div>
+
+            @* Pagination *@
+            <nav class="mt-4" aria-label="Product pagination">
+                <ul class="pagination justify-content-center">
+                    <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
+                        <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
+                                disabled="@(currentPage <= 1)">Previous</button>
+                    </li>
+                    @for (int i = 1; i <= TotalPages; i++)
+                    {
+                        var pageNum = i;
+                        <li class="page-item @(pageNum == currentPage ? "active" : "")">
+                            <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
+                        </li>
+                    }
+                    <li class="page-item @(currentPage >= TotalPages ? "disabled" : "")">
+                        <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
+                                disabled="@(currentPage >= TotalPages)">Next</button>
+                    </li>
+                </ul>
+            </nav>
+        }
+    </main>
+</div>
+
+@code {
+    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
+
+    private List<string>? categories;
+    private HashSet<string> selectedCategories = new();
+    private decimal? minPrice;
+    private decimal? maxPrice;
+    private bool inStockOnly;
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private const int PageSize = 12;
+
+    private PagedResult<Product>? result;
+    private bool isLoading;
+    private string? errorMessage;
+
+    private int TotalPages => result is null || result.TotalCount == 0
+        ? 1
+        : (int)Math.Ceiling((double)result.TotalCount / PageSize);
+
+    private int ShowingStart => result is null ? 0 : (result.Page - 1) * result.PageSize + 1;
+    private int ShowingEnd => result is null ? 0 : Math.Min(result.Page * result.PageSize, result.TotalCount);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadDataAsync();
+    }
+
+    private async Task LoadDataAsync()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            if (categories is null)
+            {
+                categories = await ProductService.GetCategoriesAsync();
+            }
+
+            var filter = new ProductFilter(
+                selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
+                minPrice,
+                maxPrice,
+                inStockOnly
+            );
+
+            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products: {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            selectedCategories.Add(category);
+        else
+            selectedCategories.Remove(category);
+    }
+
+    private async Task ApplyFilters()
+    {
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task OnSortChanged()
+    {
+        currentPage = 1;
+        await LoadDataAsync();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        if (page < 1 || page > TotalPages) return;
+        currentPage = page;
+        await LoadDataAsync();
+    }
+}
+

