@using sv_f76eba3b769e4364bcb12e86bebe0f6d.Services

<div class="card h-100 shadow-sm product-card" role="button" @onclick="OnCardClicked" style="cursor:pointer;">
    <div class="bg-secondary bg-opacity-25 d-flex align-items-center justify-content-center"
         style="height:180px;" title="@Product.Name">
        <span class="text-muted">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <div class="mb-2" title="@($"{Product.Rating:F1} out of 5")">
            @RatingStars
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="OnAddToCartClicked"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    private MarkupString RatingStars
    {
        get
        {
            int filled = (int)Math.Round(Product.Rating);
            int empty = 5 - filled;
            return new MarkupString(
                new string('★', filled) + new string('☆', empty)
            );
        }
    }

    private async Task OnCardClicked()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private void OnAddToCartClicked()
    {
        // Add-to-cart logic handled by parent or a cart service
    }
}

